# Generated by build.py from recipe.yml for recipe mqtt5-share-a-subscription. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'share.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Usage: sh share.sh PORT. Two workers subscribe to the shared subscription `$share/workers/jobs and a`n# monitor subscribes to jobs on its own, each writing what it is sent to a file. Once all three hold a`n# ping (the group hands each ping to one worker, so both workers are subscribed), six jobs are published`n# to jobs. When the workers hold all six between them, or after 20 s more, it stops the three and prints`n# how many jobs each was sent. It gives up after 40 pings.`nurl=`"mqtt5://127.0.0.1:`$1`"`nrm -f worker1.txt worker2.txt monitor.txt`ncurl -s -m 120 `"`$url/%24share/workers/jobs`" -o worker1.txt &`nw1=`$!`ncurl -s -m 120 `"`$url/%24share/workers/jobs`" -o worker2.txt &`nw2=`$!`ncurl -s -m 120 `"`$url/jobs`" -o monitor.txt &`nm=`$!`ntries=0`nuntil [ -s worker1.txt ] && [ -s worker2.txt ] && [ -s monitor.txt ]; do`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -gt 40 ]; then echo `"not all subscribed after 40 pings`" >&2; kill `"`$w1`" `"`$w2`" `"`$m`"; exit 1; fi`n  printf 'ping\n' | curl -s --data-binary @- `"`$url/jobs`"`n  sleep 0.5`ndone`nfor n in 1 2 3 4 5 6; do`n  printf 'job-%s\n' `"`$n`" | curl -s --data-binary @- `"`$url/jobs`"`ndone`ntries=0`nuntil [ `"`$(cat worker1.txt worker2.txt | grep -c job)`" -ge 6 ] && [ `"`$(grep -c job monitor.txt)`" -ge 6 ]; do`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -gt 40 ]; then break; fi`n  sleep 0.5`ndone`nkill `"`$w1`" `"`$w2`" `"`$m`"`necho `"worker 1: `$(grep -c job worker1.txt) jobs`"`necho `"worker 2: `$(grep -c job worker2.txt) jobs`"`necho `"monitor: `$(grep -c job monitor.txt) jobs`"`n")
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--topic', '"jobs;retain"', 'mqtt5://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh share.sh 8080 } finally { Stop-Process $server0 }
